const $=id=>document.getElementById(id);
const places=[
{name:'Gran Chaco',country:'Paraguay · South America',lat:-23.22307314,lon:-60.0148542,height:2200000,kind:'Forest & wilderness',desc:'A vast lowland region in the heart of South America, stretching across Paraguay, Bolivia and Argentina. Explore a mosaic of dry forests, savannas and winding rivers.',wiki:'Gran_Chaco'},
{name:'Mount Everest',country:'Nepal / China · Asia',lat:27.9881,lon:86.925,height:48000,kind:'Mountain landscape',desc:'On the border between Nepal and China, Mount Everest rises along the Himalayan range. Explore its surrounding glaciers and mountain valleys from above.',wiki:'Mount_Everest'},
{name:'Grand Canyon',country:'United States · North America',lat:36.1069,lon:-112.1129,height:65000,kind:'Canyon & national park',desc:'Carved by the Colorado River in northern Arizona, the Grand Canyon exposes layers of rock across a dramatic landscape of cliffs, plateaus and tributary canyons.',wiki:'Grand_Canyon'},
{name:'Venice',country:'Italy · Europe',lat:45.4408,lon:12.3155,height:12000,kind:'City & culture',desc:'A city spread across islands in the Venetian Lagoon. Follow the Grand Canal and explore the pattern of waterways, bridges and historic neighborhoods from above.',wiki:'Venice'},
{name:'Bhubaneswar',country:'India · Asia',lat:20.2961,lon:85.8245,height:25000,kind:'City & heritage',desc:'The capital of Odisha, in eastern India. Discover a city known for its historic temples, with planned neighborhoods and green spaces extending around the old town.',wiki:'Bhubaneswar'},
{name:'Great Barrier Reef',country:'Australia · Oceania',lat:-18.2871,lon:147.6992,height:370000,kind:'Ocean & coral reefs',desc:'Off the coast of Queensland, the Great Barrier Reef is an extensive network of coral reefs and islands in the Coral Sea. Zoom in to follow reef patterns and turquoise lagoons.',wiki:'Great_Barrier_Reef'}];
let viewer,selected=places[0],marker,mode3D=true,searchSeq=0;let toastTimer;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',5000)}
function coord(v,lat){return Math.abs(v).toFixed(4)+'° '+(lat?(v>=0?'N':'S'):(v>=0?'E':'W'))}
function tab(name){document.querySelectorAll('.tab-content').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===name))}
document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>tab(el.dataset.tab));
function details(p){selected=p;$('placeTitle').textContent=p.name;$('region').textContent=p.country||'SELECTED LOCATION';$('description').textContent=p.desc||'Explore this location on the globe. Switch to the street map for roads and local context.';$('facts').replaceChildren();const facts=[['Latitude',coord(p.lat,true)],['Longitude',coord(p.lon,false)],['Location type',p.kind||'Place'],...(p.timezone?[['Time zone',p.timezone]]:[]),...(Number.isFinite(p.population)?[['Population',p.population.toLocaleString()]]:[])];facts.forEach(([k,v])=>{let div=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;div.append(dt,dd);$('facts').append(div)});$('learn').hidden=!p.wiki;$('learn').href=p.wiki?'https://en.wikipedia.org/wiki/'+encodeURIComponent(p.wiki):'#';$('detailSource').textContent=p.source||'Location information · Curated overview';}
function fly(p){details(p);tab('details');if(!viewer){toast('The globe is still loading. Try again in a moment.');return}viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(p.lon,p.lat,p.height||35000),duration:2.3,orientation:{heading:0,pitch:-Math.PI/2,roll:0}});if(marker)viewer.entities.remove(marker);marker=viewer.entities.add({position:Cesium.Cartesian3.fromDegrees(p.lon,p.lat),point:{pixelSize:10,color:Cesium.Color.fromCssColorString('#b2efd2'),outlineColor:Cesium.Color.WHITE,outlineWidth:2,disableDepthTestDistance:Number.POSITIVE_INFINITY}});$('viewName').textContent=p.name;$('viewSub').textContent=coord(p.lat,true)+' · '+coord(p.lon,false);if(innerWidth<700)$('panel').classList.add('collapsed')}
places.forEach((p,i)=>{let b=document.createElement('button');b.className='place';let num=document.createElement('span');num.className='place-num';num.textContent=String(i+1).padStart(2,'0');let copy=document.createElement('span');copy.className='place-copy';let title=document.createElement('b');title.textContent=p.name;let small=document.createElement('small');small.textContent=p.kind+' · '+p.country.split(' · ')[0];copy.append(title,small);let pin=document.createElement('span');pin.textContent='⌖';b.append(num,copy,pin);b.onclick=()=>fly(p);$('places').append(b)});details(selected);
$('fly').onclick=()=>fly(selected);$('surprise').onclick=()=>fly(places[Math.floor(Math.random()*places.length)]);$('panelToggle').onclick=()=>$('panel').classList.toggle('collapsed');$('help').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('helpDialog').addEventListener('click',e=>{if(e.target===$('helpDialog'))$('helpDialog').close()});
async function search(q){const seq=++searchSeq;$('searchResults').replaceChildren();if(!q.trim())return;const c=q.trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);if(c){let lat=+c[1],lon=+c[2];if(Math.abs(lat)>90||Math.abs(lon)>180){toast('Latitude must be −90 to 90; longitude −180 to 180.');return}fly({name:'Pinned location',lat,lon,country:'COORDINATES',kind:'Map point'});return}let local=places.filter(p=>(p.name+' '+p.country).toLowerCase().includes(q.toLowerCase()));renderResults(local);let status=document.createElement('p');status.textContent='Searching worldwide…';$('searchResults').append(status);try{const res=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(q)+'&count=6&language=en&format=json',{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error();let data=await res.json();if(seq!==searchSeq)return;const remote=(data.results||[]).map(p=>({name:p.name,lat:p.latitude,lon:p.longitude,country:[p.admin1,p.country].filter(Boolean).join(' · '),timezone:p.timezone,population:p.population,source:'Location data · Open-Meteo / GeoNames'}));renderResults([...local,...remote]);if(!local.length&&!remote.length){status.textContent='No places found. Try a nearby city or latitude, longitude.';$('searchResults').append(status)}}catch(e){if(seq!==searchSeq)return;status.textContent=local.length?'Worldwide search is unavailable. Explore a matching destination above.':'Search is unavailable. Try a featured place or latitude, longitude.'}}
function renderResults(results){$('searchResults').replaceChildren();results.forEach(p=>{let b=document.createElement('button');b.textContent=p.name;let s=document.createElement('small');s.textContent=p.country;b.append(s);b.onclick=()=>{fly(p);$('searchResults').replaceChildren()};$('searchResults').append(b)})}
$('searchForm').onsubmit=e=>{e.preventDefault();search($('search').value)};$('search').oninput=()=>{searchSeq++;$('searchResults').replaceChildren()};
function init(){if(!window.Cesium){$('loadText').textContent='The globe could not load. Check your connection and reload.';return}try{Cesium.Ion.defaultAccessToken='';viewer=new Cesium.Viewer('globe',{baseLayer:false,baseLayerPicker:false,geocoder:false,homeButton:false,sceneModePicker:false,navigationHelpButton:false,animation:false,timeline:false,fullscreenButton:false,infoBox:false,selectionIndicator:false,requestRenderMode:true,terrainProvider:new Cesium.EllipsoidTerrainProvider()});viewer.scene.backgroundColor=Cesium.Color.fromCssColorString('#050a0e');viewer.scene.globe.baseColor=Cesium.Color.fromCssColorString('#183b4b');viewer.scene.globe.showGroundAtmosphere=true;viewer.scene.screenSpaceCameraController.minimumZoomDistance=120;viewer.scene.screenSpaceCameraController.maximumZoomDistance=35000000;viewer.camera.setView({destination:Cesium.Cartesian3.fromDegrees(-60.0148542,-23.22307314,12000000)});setLayer('satellite');$('loading').style.display='none';viewer.camera.changed.addEventListener(()=>{let c=viewer.camera.positionCartographic;$('altitude').textContent='Camera '+Math.round(c.height/1000).toLocaleString()+' km'});viewer.camera.percentageChanged=.02;let handler=new Cesium.ScreenSpaceEventHandler(viewer.scene.canvas);handler.setInputAction(e=>{let ray=viewer.camera.getPickRay(e.position),point=viewer.scene.globe.pick(ray,viewer.scene);if(!point)return;let c=Cesium.Cartographic.fromCartesian(point),lat=Cesium.Math.toDegrees(c.latitude),lon=Cesium.Math.toDegrees(c.longitude);details({name:'Pinned location',lat,lon,kind:'Map point',country:'COORDINATES',desc:'A point on our planet. Zoom in to explore its surroundings, or switch to the street map for geographic labels.'});tab('details');$('panel').classList.remove('collapsed');$('coords').textContent=coord(lat,true)+'  '+coord(lon,false);if(marker)viewer.entities.remove(marker);marker=viewer.entities.add({position:point,point:{pixelSize:9,color:Cesium.Color.fromCssColorString('#b2efd2'),outlineColor:Cesium.Color.WHITE,outlineWidth:2}})},Cesium.ScreenSpaceEventType.LEFT_CLICK)}catch(e){$('loadText').textContent='Unable to start the 3D globe. Please use a browser with WebGL enabled and reload.';console.error(e)}}
function setLayer(type){if(!viewer)return;viewer.imageryLayers.removeAll();let provider=type==='satellite'?new Cesium.UrlTemplateImageryProvider({url:'https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',maximumLevel:19,credit:'Tiles © Esri — Source: Esri, Maxar, Earthstar Geographics, and the GIS User Community'}):new Cesium.OpenStreetMapImageryProvider({url:'https://tile.openstreetmap.org/',maximumLevel:19,credit:'© OpenStreetMap contributors'});let warned=false;provider.errorEvent.addEventListener(()=>{if(!warned){warned=true;toast('Some map tiles could not load. Try the other map layer.')}});viewer.imageryLayers.addImageryProvider(provider);['satellite','streets'].forEach(id=>$(id).classList.toggle('active',id===type))}
$('satellite').onclick=()=>setLayer('satellite');$('streets').onclick=()=>setLayer('streets');$('plus').onclick=()=>{if(viewer){viewer.camera.zoomIn(viewer.camera.positionCartographic.height*.4);viewer.scene.requestRender()}};$('minus').onclick=()=>{if(viewer){viewer.camera.zoomOut(viewer.camera.positionCartographic.height*.6);viewer.scene.requestRender()}};$('home').onclick=()=>{if(viewer){viewer.camera.flyTo({destination:Cesium.Cartesian3.fromDegrees(-60,-23,18000000),orientation:{heading:0,pitch:-Math.PI/2,roll:0},duration:2});$('viewName').textContent='Our planet';$('viewSub').textContent='A world of possibilities'}};$('north').onclick=()=>{if(viewer)viewer.camera.flyTo({destination:viewer.camera.positionWC,orientation:{heading:0,pitch:-Math.PI/2,roll:0},duration:1})};$('mode').onclick=()=>{if(!viewer)return;mode3D=!mode3D;mode3D?viewer.scene.morphTo3D(1):viewer.scene.morphTo2D(1);$('mode').textContent=mode3D?'2D':'3D'};$('locate').onclick=()=>{if(!navigator.geolocation){toast('Location is not supported in this browser.');return}toast('Finding your location…');navigator.geolocation.getCurrentPosition(p=>fly({name:'Your location',lat:p.coords.latitude,lon:p.coords.longitude,country:'DEVICE LOCATION',kind:'Approximate location',desc:'Your device-reported location. Accuracy depends on your device and connection.'}),()=>toast('Location is unavailable or permission was declined. Search for your city instead.'),{timeout:12000})};init();
